// --- Isolation Forest Math Helpers ---
inline float c_factor(int n) {
    if (n <= 1) return 0.0f;
    float h = logf((float)(n - 1)) + 0.5772156649f; // Euler's constant
    return 2.0f * h - (2.0f * (float)(n - 1) / (float)n);
}

inline float compute_if_path_length(const float* features, int tree_idx) {
    const TreeNode* tree = forest[tree_idx];
    int node_idx = 0;
    float path_len = 0.0f;
    
    while (true) {
        int left = tree[node_idx].left_child;
        int right = tree[node_idx].right_child;
        if (left == -1 && right == -1) {
            int n_samples = tree[node_idx].n_node_samples;
            return path_len + c_factor(n_samples);
        }
        int feat = tree[node_idx].feature;
        float thresh = tree[node_idx].threshold;
        if (features[feat] <= thresh) {
            node_idx = left;
        } else {
            node_idx = right;
        }
        path_len += 1.0f;
    }
}

// Computes standardized Isolation Forest anomaly score: higher = more anomalous
inline float compute_if_anomaly_score(const float* features) {
    float total_path = 0.0f;
    for (int i = 0; i < NUM_TREES; i++) {
        total_path += compute_if_path_length(features, i);
    }
    float avg_path = total_path / (float)NUM_TREES;
    float c_max = c_factor(MAX_SAMPLES);
    // score = 2^(-avg_path / c_max) (matches Python -model.score_samples(X))
    return powf(2.0f, -avg_path / c_max);
}

// --- Stateful Dual-Threshold Engine ---
typedef struct {
    int suspected_counter;
    int total_alerts;
} DualThresholdState;

inline void init_dual_threshold(DualThresholdState* state) {
    state->suspected_counter = 0;
    state->total_alerts = 0;
}

// Alert outputs: 0 = Normal, 1 = Immediate Extreme, 2 = Immediate Physical, 3 = Persistent Confirmed
inline int process_decision_reading(DualThresholdState* state, float score, 
                                   float rh_overshoot, float max_flatline, bool neighbor_valid) {
    // 1. Extreme score bypass
    if (score >= T_EXTREME) {
        state->suspected_counter = 0;
        state->total_alerts++;
        return 1;
    }
    
    // 2. Strong multi-feature physical bypass
    if (USE_PHYSICAL_BYPASS) {
        if (neighbor_valid && rh_overshoot > 0.0f) {
            state->suspected_counter = 0;
            state->total_alerts++;
            return 2;
        }
        if (max_flatline >= 3.0f) {
            state->suspected_counter = 0;
            state->total_alerts++;
            return 2;
        }
    }
    
    // 3. Moderate persistence
    if (score >= T_MODERATE) {
        state->suspected_counter++;
        if (state->suspected_counter >= PERSISTENCE_K) {
            state->total_alerts++;
            return 3;
        }
        return 0; // Suspected, accumulating
    } else {
        if (state->suspected_counter > 0) state->suspected_counter--;
        return 0;
    }
}

// --- Streaming 18-Feature Extractor State ---
typedef struct {
    int warmup_counter;
    bool has_prev;
    float prev_temp;
    float prev_pres;
    float prev_rh;
    float prev_temp_delta;
    float prev_pres_delta;
    float temp_ewma;
    float temp_ewvar;
    float pres_ewma;
    float pres_ewvar;
    float rh_ewma;
    float rh_ewvar;
    int temp_flatline_count;
    int pres_flatline_count;
    int rh_flatline_count;
} EdgeExtractorState;

inline void init_edge_extractor(EdgeExtractorState* s) {
    s->warmup_counter = 0;
    s->has_prev = false;
    s->prev_temp = 0.0f;
    s->prev_pres = 0.0f;
    s->prev_rh = 0.0f;
    s->prev_temp_delta = 0.0f;
    s->prev_pres_delta = 0.0f;
    s->temp_ewma = 0.0f;
    s->temp_ewvar = 0.0f;
    s->pres_ewma = 0.0f;
    s->pres_ewvar = 0.0f;
    s->rh_ewma = 0.0f;
    s->rh_ewvar = 0.0f;
    s->temp_flatline_count = 0;
    s->pres_flatline_count = 0;
    s->rh_flatline_count = 0;
}

// Streaming feature extraction row-by-row in O(1) time
inline bool extract_features_streaming(EdgeExtractorState* s, 
                                      int hour_0_to_23,
                                      float temp, float pres, float rh,
                                      bool neighbor_valid, float n_temp, float n_pres, float n_rh,
                                      float* out_features) {
    const float alpha = 0.1f;
    const float eps_var = 1e-5f;
    const float eps_temp = 0.05f;
    const float eps_pres = 0.02f;
    const float eps_rh = 0.1f;

    if (!s->has_prev) {
        s->has_prev = true;
        s->prev_temp = temp;
        s->prev_pres = pres;
        s->prev_rh = rh;
        s->temp_ewma = temp;
        s->pres_ewma = pres;
        s->rh_ewma = rh;
        s->temp_ewvar = 0.0f;
        s->pres_ewvar = 0.0f;
        s->rh_ewvar = 0.0f;
        for (int i = 0; i < NUM_FEATURES; i++) out_features[i] = 0.0f;
        s->warmup_counter = 1;
        return false;
    }

    // 1. Deltas
    float td = temp - s->prev_temp;
    float pd = pres - s->prev_pres;
    float rhd = rh - s->prev_rh;
    out_features[FEAT_TEMP_DELTA] = td;
    out_features[FEAT_PRES_DELTA] = pd;
    out_features[FEAT_RH_DELTA] = rhd;

    // 2. Kinematics
    out_features[FEAT_TEMP_ACCEL] = td - s->prev_temp_delta;
    out_features[FEAT_PRES_ACCEL] = pd - s->prev_pres_delta;
    s->prev_temp_delta = td;
    s->prev_pres_delta = pd;

    // 3. Flatlines
    if (fabsf(td) <= eps_temp) s->temp_flatline_count++; else s->temp_flatline_count = 0;
    if (fabsf(pd) <= eps_pres) s->pres_flatline_count++; else s->pres_flatline_count = 0;
    if (fabsf(rhd) <= eps_rh)   s->rh_flatline_count++;   else s->rh_flatline_count = 0;
    out_features[FEAT_TEMP_FLATLINE] = (float)s->temp_flatline_count;
    out_features[FEAT_PRES_FLATLINE] = (float)s->pres_flatline_count;
    out_features[FEAT_RH_FLATLINE]   = (float)s->rh_flatline_count;

    // 4. EWMA Z-Scores (relative to previous baseline)
    float tz = (s->temp_ewvar > 0.0f) ? ((temp - s->temp_ewma) / (sqrtf(s->temp_ewvar) + eps_var)) : 0.0f;
    float pz = (s->pres_ewvar > 0.0f) ? ((pres - s->pres_ewma) / (sqrtf(s->pres_ewvar) + eps_var)) : 0.0f;
    float rhz = (s->rh_ewvar > 0.0f) ? ((rh - s->rh_ewma) / (sqrtf(s->rh_ewvar) + eps_var)) : 0.0f;
    out_features[FEAT_TEMP_EW_Z] = tz;
    out_features[FEAT_PRES_EW_Z] = pz;
    out_features[FEAT_RH_EW_Z]   = rhz;

    // Update EWMA/EWVAR state
    float d_t = temp - s->temp_ewma;
    s->temp_ewma += alpha * d_t;
    s->temp_ewvar = (1.0f - alpha) * (s->temp_ewvar + alpha * d_t * d_t);

    float d_p = pres - s->pres_ewma;
    s->pres_ewma += alpha * d_p;
    s->pres_ewvar = (1.0f - alpha) * (s->pres_ewvar + alpha * d_p * d_p);

    float d_rh = rh - s->rh_ewma;
    s->rh_ewma += alpha * d_rh;
    s->rh_ewvar = (1.0f - alpha) * (s->rh_ewvar + alpha * d_rh * d_rh);

    s->prev_temp = temp;
    s->prev_pres = pres;
    s->prev_rh = rh;

    // 5. Thermodynamics
    out_features[FEAT_T_RH_DISCORDANCE] = tz * rhz;
    out_features[FEAT_RH_OVERSHOOT] = (rh > 102.5f) ? (rh - 102.5f) : 0.0f;

    // 6. Spatial Residuals (Fallback to 0.0 if neighbor invalid)
    if (neighbor_valid) {
        out_features[FEAT_SPATIAL_TEMP_RES] = temp - n_temp;
        out_features[FEAT_SPATIAL_PRES_RES] = pres - n_pres;
        out_features[FEAT_SPATIAL_RH_RES]   = rh - n_rh;
    } else {
        out_features[FEAT_SPATIAL_TEMP_RES] = 0.0f;
        out_features[FEAT_SPATIAL_PRES_RES] = 0.0f;
        out_features[FEAT_SPATIAL_RH_RES]   = 0.0f;
    }

    // 7. Diurnal Encoding via LUT
    int h_idx = hour_0_to_23 % 24;
    out_features[FEAT_HOUR_SIN] = HOUR_SIN_LUT[h_idx];
    out_features[FEAT_HOUR_COS] = HOUR_COS_LUT[h_idx];

    if (s->warmup_counter < 12) {
        s->warmup_counter++;
        return false;
    }
    return true;
}

